BEGIN;SET LOCAL lock_timeout='5s';
DO $guard$ BEGIN
IF md5(pg_get_functiondef('private.bag_capacity(uuid)'::regprocedure))<>'87312fb3b0e05a767d2daf24f738f070' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.bag_capacity(uuid)'::regprocedure) IS DISTINCT FROM NULL THEN RAISE EXCEPTION 'REWARD_PRESENTATION_SOURCE_OR_ACL_DRIFT';END IF;
IF md5(pg_get_functiondef('private.pass_daily_item_preview(jsonb)'::regprocedure))<>'e0789f6bcf5425f9b97a6285fa799abd' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.pass_daily_item_preview(jsonb)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'REWARD_PRESENTATION_SOURCE_OR_ACL_DRIFT';END IF;
IF md5(pg_get_functiondef('private.oak_calendar_projection(uuid)'::regprocedure))<>'ed14aef531f11de63d5694352e6b153c' OR (SELECT proacl::text FROM pg_proc WHERE oid='private.oak_calendar_projection(uuid)'::regprocedure) IS DISTINCT FROM '{postgres=X/postgres}' THEN RAISE EXCEPTION 'REWARD_PRESENTATION_SOURCE_OR_ACL_DRIFT';END IF;
IF (SELECT extra->'perks' FROM private.store_categories WHERE key='pass') IS DISTINCT FROM '["Daily: one rotating item and 50 PokéCoins","Weekly: rotating supplies and 150 PokéCoins"]'::jsonb THEN RAISE EXCEPTION 'PASS_PERKS_COPY_DRIFT';END IF;
END $guard$;
DO $replace$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $replace$;
DO $replace$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $replace$;
DO $replace$ BEGIN EXECUTE convert_from(decode('','base64'),'UTF8');END $replace$;
UPDATE private.store_categories SET extra=jsonb_set(coalesce(extra,'{}'),'{perks}','["+25 bag space while active","Daily: 2 Berries, 1 Honey, 20 PokéCoins","Weekly: 5 Poké Balls, 3 Berries, 1 Poké Radar, 150 PokéCoins"]'::jsonb) WHERE key='pass';
COMMIT;
